        return all(g[a][b]==c for i in range(n) for j in range(n) if g[i][j]==c for a,b in refl(i,j))
    cands=[c for c in sorted(cols) if not closed(c)]
    good=[]
    for c in cands:
        out,sym=solve(g,c)
        if sym: good.append((c,out))
    if len(good)==1: return good[0][1]
    # fallback: fewest changes
